<script>
document.addEventListener('DOMContentLoaded',function(){
 const base=()=>window.getErpBasePath();
 const search=document.getElementById('rules-search'),status=document.getElementById('rules-status'),rows=[...document.querySelectorAll('[data-rule-row]')],empty=document.getElementById('rules-empty');
 function filterRules(){let q=(search?search.value:'').trim().toLowerCase(),st=status?status.value:'all',shown=0;rows.forEach(r=>{let pass=(!q||(r.dataset.search||'').includes(q))&&(st==='all'||r.dataset.status===st);r.classList.toggle('ux-hidden',!pass);if(pass)shown++});if(empty)empty.classList.toggle('ux-hidden',shown!==0)}
 if(search)search.addEventListener('input',filterRules);if(status)status.addEventListener('change',filterRules);
 function initRuleForm(scope){const form=scope.querySelector('[data-matching-rule-form]');if(!form)return;const cfu=form.querySelector('#matching-rule-cfu'),dds=form.querySelector('#matching-rule-dds'),direction=form.querySelector('#matching-rule-direction');if(!cfu||!dds)return;let map={};try{map=JSON.parse(cfu.dataset.ddsMap||'{}')}catch(e){};function syncDirection(){const opt=dds.selectedOptions[0];if(!opt)return;const d=(opt.dataset.direction||'').toUpperCase();if(direction)direction.value=(d==='INCOME'||d==='EXPENSE')?d:'';}function refresh(){const id=String(cfu.value||''),hasMap=id!==''&&Object.prototype.hasOwnProperty.call(map,id),allowed=new Set((map[id]||[]).map(String)),current=String(dds.value||'');[...dds.options].forEach((o,i)=>{if(i===0)return;const show=!id||!hasMap||allowed.has(String(o.value));o.hidden=!show;o.disabled=!show});if(current&&dds.selectedOptions[0]&&dds.selectedOptions[0].disabled)dds.value='';syncDirection()}cfu.addEventListener('change',refresh);dds.addEventListener('change',syncDirection);refresh();}
 function loadForm(modalId,bodyId,url){const body=document.getElementById(bodyId);body.innerHTML='<div class="modal-body"><div class="empty-state compact"><p>Загрузка...</p></div></div>';window.openModal(modalId);fetch(base()+url).then(r=>r.text()).then(h=>{body.innerHTML=h;initRuleForm(body)}).catch(()=>body.innerHTML='<div class="modal-body"><div class="form-alert alert-error">Не удалось загрузить форму.</div></div>')}
 const create=document.getElementById('matching-rule-create-btn');if(create)create.addEventListener('click',()=>loadForm('matching-rule-create-modal','matching-rule-create-modal-body','/company/finance/settings/matching-rules/create'));
 function openEdit(id){loadForm('matching-rule-edit-modal','matching-rule-edit-modal-body','/company/finance/settings/matching-rules/edit?id='+encodeURIComponent(id))}
 rows.forEach(row=>row.addEventListener('dblclick',()=>openEdit(row.dataset.editId)));
 function openPreview(id){const body=document.getElementById('matching-rule-preview-body');body.innerHTML='<div class="ux-summary-strip"><div><strong>Загрузка...</strong></div></div>';window.openModal('matching-rule-preview-modal');fetch(base()+'/company/finance/settings/matching-rules/preview?id='+encodeURIComponent(id)).then(r=>r.json()).then(data=>{let h='<div class="ux-summary-strip"><div><strong>Проверка правила</strong></div><div>Совпадений: '+Number(data.total_matches||0)+'</div></div>';if(data.results&&data.results.length){h+='<div class="table-scroll"><table class="table"><thead><tr><th>Дата</th><th>Контрагент</th><th>Сумма</th><th>Назначение</th><th>Результат</th></tr></thead><tbody>';data.results.forEach(r=>h+='<tr><td>'+r.operation_date+'</td><td>'+r.counterparty_name+'</td><td class="col-mono">'+r.amount+'</td><td>'+r.purpose+'</td><td>'+r.result+'</td></tr>');h+='</tbody></table></div>'}else h+='<div class="ux-empty"><strong>Совпадений нет</strong>Операции не соответствуют этому правилу.</div>';body.innerHTML=h}).catch(()=>body.innerHTML='<div class="form-alert alert-error">Не удалось выполнить проверку.</div>')}
 document.addEventListener('click',function(e){const preview=e.target.closest('[data-rule-preview-from-edit]');if(preview){openPreview(preview.dataset.rulePreviewFromEdit);return}const toggle=e.target.closest('[data-rule-toggle-from-edit]');if(toggle){const id=toggle.dataset.ruleToggleFromEdit,active=toggle.dataset.ruleActive==='1';document.getElementById('matching-rule-toggle-id').value=id;document.getElementById('matching-rule-toggle-title').textContent=active?'Отключить правило?':'Включить правило?';document.getElementById('matching-rule-toggle-copy').textContent=active?'Правило перестанет участвовать в автоматическом разнесении. Уже выполненные разнесения останутся без изменений.':'Правило снова начнёт автоматически применяться к подходящим операциям.';document.getElementById('matching-rule-toggle-confirm').textContent=active?'Отключить':'Включить';window.openModal('matching-rule-toggle-modal');return}const del=e.target.closest('[data-rule-delete-from-edit]');if(del){document.getElementById('matching-rule-delete-id').value=del.dataset.ruleDeleteFromEdit;window.openModal('matching-rule-delete-modal')}});
});
</script>
